require_once __DIR__.'/inc/core.php';$u=require_login();$message='';$error='';
try{$message=post_action($u)??'';}catch(Throwable $e){$error=$e->getMessage();}
$cuentas=accounts($u);$apis=api_list($u);$users=is_super($u)?db()->query('SELECT u.id,u.usuario,u.nombre,u.rol,u.activo,group_concat(c.nombre,", ") cuentas FROM usuarios u LEFT JOIN membresias m ON m.usuario_id=u.id LEFT JOIN cuentas c ON c.id=m.cuenta_id GROUP BY u.id ORDER BY u.id DESC')->fetchAll():[];
$ids=array_map(fn($a)=>(int)$a['id'],$apis);$stats=[];$daily=[];
if($ids){$marks=implode(',',array_fill(0,count($ids),'?'));$q=db()->prepare("SELECT api_id,COUNT(*) total,SUM(CASE WHEN estado BETWEEN 200 AND 299 THEN 1 ELSE 0 END) exitos,ROUND(AVG(duracion_ms),1) latencia,MAX(fecha) ultima FROM solicitudes WHERE api_id IN ($marks) GROUP BY api_id");$q->execute($ids);foreach($q as $r)$stats[$r['api_id']]=$r;
$q=db()->prepare("SELECT substr(fecha,1,10) dia,COUNT(*) total FROM solicitudes WHERE api_id IN ($marks) AND fecha>=datetime('now','-29 days') GROUP BY substr(fecha,1,10) ORDER BY dia");$q->execute($ids);$daily=$q->fetchAll();}
$tab=(string)($_GET['tab']??'resumen');if(!in_array($tab,['resumen','apis','estadisticas','cuentas','usuarios','perfil','documentacion'],true))$tab='resumen';
$newkey=$_SESSION['new_key']??null;unset($_SESSION['new_key']);
