<?php if($tab==='resumen'||$tab==='estadisticas'):?>
<div class="kpis"><article><small>APIs visibles</small><strong><?=count($apis)?></strong></article><article><small>Llamadas totales</small><strong><?=array_sum(array_column($stats,'total'))?></strong></article><article><small>Correctas</small><strong><?=array_sum(array_column($stats,'exitos'))?></strong></article><article><small>Cuentas</small><strong><?=count($cuentas)?></strong></article></div>
<section class="panel"><h3>Llamadas durante los últimos 30 días</h3><div id="chart" class="chart" data-days="<?=h(json_encode($daily))?>"></div></section>
<section class="panel"><h3>Uso por API</h3><div class="table-wrap"><jocarsa-tabla><table><thead><tr><th>API</th><th>Cuenta</th><th>Llamadas</th><th>Correctas</th><th>Errores</th><th>Latencia media</th><th>Última llamada (UTC)</th></tr></thead><tbody><?php foreach($apis as $a):$s=$stats[$a['id']]??[];$n=(int)($s['total']??0);$ok=(int)($s['exitos']??0);?><tr><td><?=h($a['nombre'])?></td><td><?=h($a['cuenta'])?></td><td><?=$n?></td><td><?=$ok?></td><td><?=$n-$ok?></td><td><?=h($s['latencia']??'—')?> ms</td><td><?=h($s['ultima']??'—')?></td></tr><?php endforeach;?></tbody></table></jocarsa-tabla></div></section>
<?php endif;?>
<?php if($tab==='apis'):?>
<section class="panel"><h3>Crear API</h3><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="api"><label>Nombre<input name="nombre" required maxlength="120" placeholder="Informe de ventas"></label><label>Identificador de URL<input name="slug" required pattern="[a-z0-9][a-z0-9-]{2,63}" placeholder="ventas-mensuales"></label><label>Cuenta<select name="cuenta_id" required><?php foreach($cuentas as $c):?><option value="<?=$c['id']?>"><?=h($c['nombre'])?></option><?php endforeach;?></select></label><button <?=!$cuentas?'disabled':''?>>Crear API y generar clave</button></form></section>
<section class="panel"><h3>APIs registradas</h3><div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Cuenta</th><th>URL relativa</th><th>Clave (prefijo)</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php foreach($apis as $a):?><tr><td><?=h($a['nombre'])?></td><td><?=h($a['cuenta'])?></td><td><code>api.php?ruta=<?=h($a['slug'])?></code></td><td><code><?=h($a['key_prefix'])?>…</code></td><td><?=$a['activo']?'Activa':'Inactiva'?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="toggle_api"><input type="hidden" name="api_id" value="<?=$a['id']?>"><button><?=$a['activo']?'Desactivar':'Activar'?></button></form></td></tr><?php endforeach;?></tbody></table></div></section>
<?php endif;?>
<?php if($tab==='cuentas'&&is_super($u)):?><section class="panel"><h3>Nueva cuenta</h3><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="cuenta"><label>Nombre de cuenta<input name="nombre" required></label><button>Crear cuenta</button></form></section><section class="panel"><h3>Cuentas existentes</h3><table><thead><tr><th>ID</th><th>Nombre</th><th>Creada</th></tr></thead><tbody><?php foreach($cuentas as $c):?><tr><td><?=$c['id']?></td><td><?=h($c['nombre'])?></td><td><?=h($c['creado'])?></td></tr><?php endforeach;?></tbody></table></section><?php endif;?>
<?php if($tab==='usuarios'&&is_super($u)):?><section class="panel"><h3>Crear usuario</h3><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="usuario"><label>Usuario<input name="usuario" required></label><label>Nombre<input name="nombre" required></label><label>Contraseña inicial<input type="password" name="password" minlength="8" required></label><label>Rol<select name="rol"><option value="usuario">Usuario</option><option value="admin">Administrador</option></select></label><label>Cuenta asignada<select name="cuenta_id"><option value="0">Sin cuenta</option><?php foreach($cuentas as $c):?><option value="<?=$c['id']?>"><?=h($c['nombre'])?></option><?php endforeach;?></select></label><button>Crear usuario</button></form></section><section class="panel"><h3>Usuarios</h3><table><thead><tr><th>Usuario</th><th>Nombre</th><th>Rol</th><th>Cuentas</th></tr></thead><tbody><?php foreach($users as $v):?><tr><td><?=h($v['usuario'])?></td><td><?=h($v['nombre'])?></td><td><?=h($v['rol'])?></td><td><?=h($v['cuentas']??'—')?></td></tr><?php endforeach;?></tbody></table></section><?php endif;?>
<?php if($tab==='perfil'):?><section class="panel"><h3>Cambiar contraseña</h3><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="password"><label>Contraseña actual<input type="password" name="actual" required></label><label>Nueva contraseña (mínimo 12 caracteres)<input type="password" name="nueva" minlength="12" required></label><button>Cambiar contraseña</button></form></section><?php endif;?>
<?php if($tab==='documentacion'):?><section class="panel"><h3>Consumir un informe</h3><p>Envía un POST con el JSON del documento y la cabecera <code>X-API-Key</code>. La respuesta correcta es HTML autónomo, con CSS incluido.</p><pre>curl -X POST "https://TU-DOMINIO/RUTA/api.php?ruta=ventas-mensuales" \
